import ru.fragment.logoeditor.*;
import java.io.*;
import java.util.*;
public final class UpdateNativeTests {
 static void ok(boolean value,String message){if(!value)throw new AssertionError(message);}
 static UpdatePolicy.Release release(int code,String channel,String at){UpdatePolicy.Release r=new UpdatePolicy.Release();r.code=code;r.channel=channel;r.version="1.0."+code;r.publishedAt=at;r.minSdk=23;r.abis=new String[]{"universal"};r.packageName="ru.fragment.logoeditor";return r;}
 interface Action{void run()throws Exception;}static void rejects(Action a,String name)throws Exception{try{a.run();}catch(Exception expected){return;}throw new AssertionError("Accepted invalid "+name);}
 public static void main(String[] args)throws Exception{
  String pkg="ru.fragment.logoeditor";String[] abis={"arm64-v8a"};UpdatePolicy.Release stable=release(10,"stable","2026-11-18T01:00:00Z"),test=release(11,"testing","2026-11-18T02:00:00Z"),exp=release(12,"experimental","2026-11-18T03:00:00Z");List<UpdatePolicy.Release> all=Arrays.asList(stable,test,exp);
  ok(UpdatePolicy.choose(all,false,35,abis,pkg,9)==exp,"default includes experimental");ok(UpdatePolicy.choose(all,true,35,abis,pkg,9)==stable,"stable-only ignores newer tests");exp.minSdk=99;ok(UpdatePolicy.choose(all,false,35,abis,pkg,9)==test,"skip incompatible API");exp.minSdk=23;exp.abis=new String[]{"x86"};ok(UpdatePolicy.choose(all,false,35,abis,pkg,9)==test,"skip wrong ABI");exp.abis=new String[]{"universal"};exp.packageName="wrong.package";ok(UpdatePolicy.choose(all,false,35,abis,pkg,9)==test,"skip wrong package");ok(!UpdatePolicy.hasStable(Arrays.asList(test,exp)),"no stable message condition");ok(UpdatePolicy.choose(all,true,35,abis,pkg,10)==null,"no downgrade");
  ok(UpdatePolicy.identity(stable,pkg,10,stable.version),"matching package identity");ok(!UpdatePolicy.identity(stable,"wrong",10,stable.version),"wrong package rejected");ok(!UpdatePolicy.identity(stable,pkg,11,stable.version),"wrong code rejected");ok(!UpdatePolicy.identity(stable,pkg,10,"bad.version"),"wrong version name rejected");
  ok(!UpdatePolicy.shouldPrompt(12,12,100,50,false,false),"Later suppresses only same installation prompt");ok(UpdatePolicy.shouldPrompt(13,12,100,50,false,false),"newer release still prompts");ok(UpdatePolicy.shouldPrompt(12,12,100,50,true,false),"manual prompt bypasses Later");
  final File valid=new File(args[0]);final long size=valid.length();final String sha=UpdateCache.sha256(valid);final Set<String> signers=new HashSet<String>(Arrays.asList(args[1]));ApkIntegrity.verify(valid,size,sha,signers,23);
  rejects(new Action(){public void run()throws Exception{ApkIntegrity.verify(valid,size+1,sha,signers,23);}},"size");rejects(new Action(){public void run()throws Exception{ApkIntegrity.verify(valid,size,new String(new char[64]).replace('\0','0'),signers,23);}},"SHA-256");rejects(new Action(){public void run()throws Exception{ApkIntegrity.verify(valid,size,sha,new HashSet<String>(Arrays.asList("bad")),23);}},"signer");rejects(new Action(){public void run()throws Exception{ApkIntegrity.verify(valid,size,sha,signers,24);}},"minSdk");
  final File dir=new File(args[2]);dir.mkdirs();final File target=new File(dir,"cached.apk");target.delete();final int[] downloads={0};UpdateCache.Downloader downloader=new UpdateCache.Downloader(){public void download(File f)throws Exception{downloads[0]++;copy(valid,f);}};UpdateCache.Verifier verifier=new UpdateCache.Verifier(){public void verify(File f)throws Exception{ApkIntegrity.verify(f,size,sha,signers,23);}};
  UpdateCache.obtain(target,downloader,verifier);ok(downloads[0]==1,"first download");UpdateCache.obtain(target,downloader,verifier);ok(downloads[0]==1,"resume reuses fully verified APK");
  // Deferred installation does not gate fetching a different allowed build.
  File next=new File(dir,"next.apk");next.delete();UpdateCache.obtain(next,downloader,verifier);ok(downloads[0]==2,"new allowed build downloads despite deferred old install");
  RandomAccessFile damaged=new RandomAccessFile(target,"rw");damaged.setLength(100);damaged.close();UpdateCache.obtain(target,downloader,verifier);ok(downloads[0]==3,"corrupt cache downloads once more");
  File recovered=new File(dir,"recovered.apk");recovered.delete();copy(valid,new File(recovered+".part.apk"));UpdateCache.obtain(recovered,downloader,verifier);ok(downloads[0]==3,"complete download interrupted before rename is reused");
  File interrupted=new File(dir,"interrupted.apk");interrupted.delete();try{UpdateCache.obtain(interrupted,new UpdateCache.Downloader(){public void download(File f)throws Exception{FileOutputStream out=new FileOutputStream(f);out.write(1);out.close();throw new IOException("network interrupted");}},verifier);}catch(IOException expected){}ok(!interrupted.exists()&&!new File(interrupted+".part.apk").exists(),"incomplete files never become ready");
  final File tampered=new File(args[3]);rejects(new Action(){public void run()throws Exception{ApkIntegrity.verify(tampered,tampered.length(),UpdateCache.sha256(tampered),signers,23);}},"cryptographic tampering even with recomputed file hash");
  System.out.println("PASS: native all/stable modes, experimental and compatibility selection, identity checks, real APK crypto/size/hash/signer/minSdk checks, cache reuse, corruption, interrupted downloads and Later isolation");
 }
 static void copy(File a,File b)throws Exception{InputStream in=new FileInputStream(a);OutputStream out=new FileOutputStream(b);try{byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}finally{in.close();out.close();}}
}
